css:
.bb-dccn { font-family: "Times New Roman", "Liberation Serif", Tinos, serif; font-size: 12pt; color: #000; line-height: 1.35; }
.bb-dccn table { width: 100%; border-collapse: collapse; border: none; }
.bb-dccn td { border: none !important; padding: 1px 3px !important; vertical-align: top !important; }
.bb-dccn .hdr td { font-size: 11pt; }
.bb-dccn .hdr .co-name { font-size: 14pt; font-weight: bold; }
.bb-dccn .logo { width: 100%; max-width: 230px; }
.bb-dccn .title { text-align: center; font-size: 18pt; font-weight: bold; margin: 10px 0 8px; }
.bb-dccn .basis { font-style: italic; }
.bb-dccn .sec { font-weight: bold; margin-top: 6px; }
.bb-dccn .party td.lbl { width: 21%; }
.bb-dccn .party td.mst { width: 26%; font-weight: bold; }
.bb-dccn .fig td { height: 20px; vertical-align: middle !important; }
.bb-dccn .fig td.lbl { width: 27%; padding-left: 8.5%; }
.bb-dccn .fig td.sub { font-style: italic; }
.bb-dccn .fig td.colon { width: 2%; }
.bb-dccn .fig td.amt { width: 22%; text-align: right; }
.bb-dccn .fig td.unit { width: 8%; padding-left: 8px; }
.bb-dccn .fig td.dir { font-style: italic; }
.bb-dccn .b { font-weight: bold; }
.bb-dccn .bi { font-weight: bold; font-style: italic; }
.bb-dccn .sign td { text-align: center; width: 50%; }
.bb-dccn .sign .note { font-style: italic; font-size: 10pt; }

html:
{%- macro money(v) -%}{{ "{:,.0f}".format((v or 0)|float|abs).replace(",", ".") }}{%- endmacro -%}
{%- macro dmy(d) -%}{{ frappe.utils.formatdate(d, "dd/MM/yyyy") if d else "…" }}{%- endmacro -%}
{%- macro dir_note(direction) -%}{% if direction and direction != "Bằng 0" %}({{ direction }}){% endif %}{%- endmacro -%}
{%- set is_supplier = true -%}
{%- set s = frappe.get_cached_doc("Debt Reconciliation Settings") -%}
{%- set co = frappe.db.get_value("Company", doc.company, ["company_name", "tax_id", "company_logo"], as_dict=True) or {} -%}
{%- set co_name = s.company_legal_name or co.company_name or doc.company -%}
{%- set co_tax = co.tax_id or s.company_tax_id or "…" -%}
{%- set co_addr = s.company_address or "…" -%}
{%- set logo = co.company_logo or "/assets/erpnext/images/miyano-logo-wide.jpg" -%}
{%- set p_name = doc.party_name or doc.party -%}
{%- set pd = frappe.utils.getdate(doc.posting_date) -%}
{%- set owed_dir = "Dư Có" if is_supplier else "Dư Nợ" -%}
<div class="bb-dccn">
<table class="hdr"><tr>
<td style="width:28%; vertical-align:middle;"><img class="logo" src="{{ logo }}"></td>
<td style="width:72%;">
<div class="co-name">{{ co_name }}</div>
<div>Trụ sở: {{ co_addr }}</div>
{% if s.hard_copy_address %}<div>VPGD: {{ s.hard_copy_address }}</div>{% endif %}
<div>Tel: {{ s.company_phone or "…" }}</div>
<table><tr><td style="width:45%; padding:0;">Mã số thuế: {{ co_tax }}</td><td style="padding:0;">{% if s.company_email %}Email: {{ s.company_email }}{% endif %}</td></tr></table>
</td></tr></table>

<table style="margin-top:2px;"><tr><td style="width:64%;"></td><td style="width:8%;">Số:</td><td>{{ doc.statement_no }}</td></tr>
<tr><td></td><td>Ngày</td><td>{{ dmy(doc.posting_date) }}</td></tr></table>

<div class="title">BIÊN BẢN ĐỐI CHIẾU &amp; XÁC NHẬN CÔNG NỢ</div>

<div class="basis">- Căn cứ vào Hợp đồng nguyên tắc số {{ doc.framework_contract_no or "…....." }} ngày {{ dmy(doc.framework_contract_date) if doc.framework_contract_date else "…......" }} ký giữa {{ co_name }}</div>
<div class="basis">và {{ p_name }}</div>
<div class="basis">- Căn cứ vào thực hiện các giao dịch thương mại và mua bán giữa các bên sau đây.</div>
<div style="margin-top:6px;">Hôm nay, ngày {{ "%02d"|format(pd.day) }} tháng {{ "%02d"|format(pd.month) }} năm {{ pd.year }}, tại Hà Nội. Chúng tôi gồm có:</div>

{%- macro party_block(title, name, tax, addr_label, addr, phone, rep, rep_title) -%}
<table class="party" style="margin-top:6px;">
<tr><td class="lbl b">{{ title }}</td><td class="b">: {{ name }}</td><td class="mst">MST: {{ tax or "…..............." }}</td></tr>
<tr><td class="lbl">{{ addr_label }}</td><td colspan="2">: {{ addr or "…........................................................................................" }}</td></tr>
<tr><td class="lbl"></td><td colspan="2">Tel: {{ phone or "(+84)" }}</td></tr>
<tr><td class="lbl">1. Đại diện Ông (bà)</td><td>: {{ rep or "" }}</td><td>Chức vụ: {{ rep_title or "" }}</td></tr>
<tr><td class="lbl">2. Đại diện Ông (bà)</td><td>:</td><td>Chức vụ:</td></tr>
</table>
{%- endmacro -%}

{%- set miyano = [co_name, co_tax, "Địa chỉ", co_addr, s.company_phone, doc.company_representative, doc.company_representative_title] -%}
{%- set partner = [p_name, doc.party_tax_id, "Trụ sở giao dịch", doc.party_address, doc.party_phone, doc.party_representative, doc.party_representative_title] -%}
{%- set side_a = partner if is_supplier else miyano -%}
{%- set side_b = miyano if is_supplier else partner -%}
{{ party_block("I. Bên bán (Bên A)", *side_a) }}
{{ party_block("II. Bên mua (Bên B)", *side_b) }}

<div class="bi" style="margin-top:10px;">Hai bên cùng nhau thống nhất đối chiếu và xác nhận công nợ từ ngày {{ dmy(doc.from_date) }} đến ngày {{ dmy(doc.to_date) }}, nội dung như sau:</div>

<div class="sec">[i] SỐ DƯ ĐẦU KỲ</div>
<table class="fig">
<tr><td class="lbl b">Dư nợ/có đầu kỳ</td><td class="colon">:</td><td class="amt b">{{ money(doc.opening_principal + doc.opening_interest) }}</td><td class="unit b">Đồng</td><td class="dir">{{ dir_note(doc.opening_direction) }}</td></tr>
<tr><td class="lbl bi">Gồm:</td><td></td><td></td><td></td><td></td></tr>
<tr><td class="lbl sub">(1) Giá trị gốc</td><td class="colon">:</td><td class="amt">{{ money(doc.opening_principal) }}</td><td class="unit">Đồng</td><td></td></tr>
<tr><td class="lbl sub">(2) Lãi quá hạn</td><td class="colon">:</td><td class="amt">{{ money(doc.opening_interest) }}</td><td class="unit">Đồng</td><td></td></tr>
</table>

<div class="sec">[ii] SỐ PHÁT SINH TRONG KỲ</div>
<table class="fig">
<tr><td class="lbl b">1. Phát sinh có trong kỳ</td><td class="colon">:</td><td class="amt b">{{ money(doc.credit_in_period + doc.interest_in_period) }}</td><td class="unit b">Đồng</td><td></td></tr>
<tr><td class="lbl sub">(1) Giá trị gốc</td><td class="colon">:</td><td class="amt">{{ money(doc.credit_in_period) }}</td><td class="unit">Đồng</td><td></td></tr>
<tr><td class="lbl sub">(2) Lãi quá hạn</td><td class="colon">:</td><td class="amt">{{ money(doc.interest_in_period) }}</td><td class="unit">Đồng</td><td></td></tr>
<tr><td class="lbl b">2. Phát sinh nợ trong kỳ</td><td class="colon b">:</td><td class="amt b">{{ money(doc.debit_in_period) }}</td><td class="unit b">Đồng</td><td></td></tr>
</table>

<div class="sec">[iii] SỐ DƯ CUỐI KỲ</div>
<table class="fig">
<tr><td class="lbl b">Dư nợ/có cuối kỳ</td><td class="colon">:</td><td class="amt b">{{ money(doc.closing_balance) }}</td><td class="unit b">Đồng</td><td class="dir">{{ dir_note(doc.balance_direction) }}</td></tr>
</table>

<div class="sec" style="margin-top:8px;">[iv] KẾT LUẬN:</div>
{%- set debtor = co_name if is_supplier else p_name -%}
{%- set creditor = p_name if is_supplier else co_name -%}
<div>Tính đến hết ngày {{ dmy(doc.to_date) }},
{% if doc.balance_direction == "Bằng 0" -%}
{{ co_name }} và {{ p_name }} không còn công nợ, số tiền là:
{%- elif doc.balance_direction == owed_dir -%}
{{ debtor }} còn nợ tiền mua hàng của {{ creditor }} là:
{%- else -%}
{{ debtor }} đã thanh toán trước cho {{ creditor }} là:
{%- endif %}</div>
<table class="fig">
<tr><td style="width:27%;">Tổng số tiền bằng số</td><td class="colon">:</td><td class="amt b">{{ money(doc.closing_balance) }}</td><td class="unit">Đồng</td><td></td></tr>
<tr><td style="width:27%;">Tổng số tiền bằng chữ</td><td class="colon">:</td><td colspan="3" class="bi">{{ so_thanh_chu(doc.closing_balance|float|abs) }} ./.</td></tr>
</table>

<div style="margin-top:8px;">Rất mong Quý công ty ký, đóng dấu xác nhận công nợ và gửi về {{ co_name }} trước ngày {{ dmy(doc.response_deadline) }}.</div>
<div>Theo địa chỉ VPGD của Công ty chúng tôi:</div>
<div class="bi" style="padding-left:8.5%;">{{ co_name }}</div>
<div class="bi" style="padding-left:8.5%;">{{ s.hard_copy_address or "" }}</div>
{% if s.contact_line %}<div class="bi" style="padding-left:8.5%;">Liên hệ: {{ s.contact_line }}</div>{% endif %}

<div style="margin-top:10px;">Biên bản này được lập thành 02 bản, mỗi bên giữ 01 bản và có giá trị pháp lý như nhau./.</div>

<table class="sign" style="margin-top:14px; page-break-inside: avoid;">
<tr><td class="b">ĐẠI DIỆN BÊN A (BÊN BÁN)</td><td class="b">ĐẠI DIỆN BÊN B (BÊN MUA)</td></tr>
<tr><td class="note">(Ký, đóng dấu và ghi rõ họ tên)</td><td class="note">(Ký, đóng dấu và ghi rõ họ tên)</td></tr>
<tr><td style="height:100px;"></td><td></td></tr>
</table>
</div>
